export const privateTask48UsageGeneratorSource = "import { Database } from \"bun:sqlite\";\nimport { createHash } from \"node:crypto\";\nimport { readFile, writeFile } from \"node:fs/promises\";\nimport { gzipSync } from \"node:zlib\";\n\nimport { createStoredAccountUsageSnapshot } from \"./src/domain/usage-metrics\";\nimport { initializeStatePaths, resolveStatePaths } from \"./src/storage/paths\";\nimport { StateStore } from \"./src/storage/state-store\";\n\nconst sourceRevision = \"3f6ac733dc17b3eec881ad98f2d65faadbcbaf37\";\nconst paths = resolveStatePaths({\n  homeDirectory: `${import.meta.dir}/fixture-home`,\n  platform: \"darwin\",\n});\nawait initializeStatePaths(paths);\nconst store = new StateStore(paths, { now: () => 1_001 });\nconst initial = new Database(paths.database, { readonly: true, strict: true });\nif ((initial.query(\"PRAGMA user_version\").get() as { user_version: number }).user_version !== 48) {\n  throw new Error(\"ARCHIVED_SCHEMA_NOT_48\");\n}\ninitial.close();\nconst profile = store.nextProfileGeneration(store.createProfile(\"Private task usage\").id);\nif (!store.setProfileState(profile.id, profile.processGeneration, \"signed_in\", {\n  email: \"private48-usage@example.com\",\n  plan: \"Plus\",\n})) throw new Error(\"ARCHIVED_PROFILE_SETUP_FAILED\");\nconst authority = store.requireProviderAccountAuthority(profile.id, \"codex\");\nconst fingerprint = \"a\".repeat(64);\nconst payload = (lifetimeTokens: number, usedPercent: number) => ({\n  usage: {\n    summary: {\n      lifetimeTokens,\n      peakDailyTokens: null,\n      longestRunningTurnSec: null,\n      currentStreakDays: null,\n      longestStreakDays: null,\n    },\n    dailyUsageBuckets: null,\n  },\n  rateLimits: {\n    primary: {\n      limitId: \"codex\",\n      limitName: \"Codex\",\n      planType: \"plus\",\n      rateLimitReachedType: null,\n      primary: { usedPercent, windowDurationMins: 300, resetsAt: 3_600 },\n      secondary: { usedPercent: 20, windowDurationMins: 10_080, resetsAt: 604_800 },\n    },\n    byLimitId: null,\n    resetCreditsAvailable: 0,\n  },\n});\nconst first = createStoredAccountUsageSnapshot({\n  accountFingerprint: fingerprint,\n  daemonGeneration: 1,\n  providerGeneration: authority.processGeneration,\n  observedAt: 10_000,\n  receivedAt: 1_000,\n  sourceSequence: 1,\n  previousPayload: null,\n  providerPayload: payload(100, 10),\n});\nconst third = createStoredAccountUsageSnapshot({\n  accountFingerprint: fingerprint,\n  daemonGeneration: 1,\n  providerGeneration: authority.processGeneration,\n  observedAt: 30_000,\n  receivedAt: 1_001,\n  sourceSequence: 3,\n  previousPayload: first,\n  providerPayload: payload(300, 30),\n});\nstore.recordUsage(profile.id, 1, 10_000, first, authority);\nstore.recordUsagePollFailure(profile.id, fingerprint, 2, 20_000, authority);\nstore.recordUsage(profile.id, 3, 30_000, third, authority);\nconst metadata = ([\n  [\"usage_snapshot\", 1], [\"usage_snapshot\", 3],\n  [\"usage_poll_failure\", 2], [\"usage_upload_anchor\", 1],\n] as const).map(([scope, revision]) => {\n  const value = store.readCodexUsageAuthorityMetadata(scope, profile.id, revision);\n  if (value.mode !== \"mutation_authoritative\"\n    || JSON.stringify(value.authority) !== JSON.stringify(authority)\n    || value.binding.processGeneration !== authority.processGeneration\n    || value.canAuthorizeQuota !== (scope === \"usage_snapshot\")) {\n    throw new Error(\"ARCHIVED_USAGE_AUTHORITY_NOT_EXACT\");\n  }\n  return { scope, revision, value };\n});\nconst projection = store.latestProviderUsage(authority.providerAccountId);\nif (projection === null) throw new Error(\"ARCHIVED_USAGE_PROJECTION_MISSING\");\nstore.close();\n\nconst database = new Database(paths.database, { strict: true });\ndatabase.exec(\"PRAGMA wal_checkpoint(TRUNCATE)\");\ndatabase.exec(\"PRAGMA query_only=ON\");\nconst schemaVersion = (database.query(\"PRAGMA user_version\").get() as { user_version: number }).user_version;\nconst rows = {\n  snapshots: database.query(\"SELECT * FROM usage_snapshots ORDER BY profile_id,source_revision\").all(),\n  failures: database.query(\"SELECT * FROM usage_poll_failures ORDER BY profile_id,source_revision\").all(),\n  anchors: database.query(\"SELECT * FROM usage_cloud_upload_anchors ORDER BY profile_id,source_revision\").all(),\n  revisions: database.query(\"SELECT * FROM usage_revision_authority ORDER BY profile_id\").all(),\n  authorities: database.query(`SELECT * FROM account_scoped_provider_authorities\n    WHERE scope_kind IN ('usage_snapshot','usage_poll_failure','usage_upload_anchor')\n    ORDER BY scope_kind,scope_id`).all(),\n};\nif (schemaVersion !== 48 || rows.snapshots.length !== 2 || rows.failures.length !== 1\n  || rows.anchors.length !== 1 || rows.authorities.length !== 4) {\n  throw new Error(\"ARCHIVED_USAGE_FIXTURE_INCOMPLETE\");\n}\nconst migrations = database.query(\"SELECT version,applied_at FROM migrations ORDER BY version\").all();\nconst inspectionChanges = database.query(\"SELECT total_changes() AS count\").get();\ndatabase.close();\nconst bytes = await readFile(paths.database);\nconst source = await readFile(import.meta.filename, \"utf8\");\nconst meta = {\n  sourceRevision,\n  schemaVersion,\n  databaseSha256: createHash(\"sha256\").update(bytes).digest(\"hex\"),\n  databaseBytes: bytes.byteLength,\n  generatorSha256: createHash(\"sha256\").update(source).digest(\"hex\"),\n  profileId: profile.id,\n  authority,\n  fingerprint,\n  first,\n  third,\n  metadata,\n  projection,\n  rows,\n  migrations,\n};\nawait writeFile(`${import.meta.dir}/private48-usage-output.json`, JSON.stringify({\n  meta, source, gzip: gzipSync(bytes).toString(\"base64\"),\n}), { mode: 0o600, flag: \"wx\" });\nconsole.log(JSON.stringify({ schemaVersion, inspectionChanges, databaseSha256: meta.databaseSha256,\n  authority, scopes: metadata.map(({ scope, revision, value }) => ({ scope, revision, mode: value.mode })),\n  output: `${import.meta.dir}/private48-usage-output.json` }));\n";

